/*
  Late Nite Halloween TV - TOP BANNER for CyTube (SELF-CONTAINED)
  - Uses the final blended Halloween artwork as a single top banner image.
  - Full image shown without cropping.
  - No scroll-down text.
  - No separate bat animation.
  - Subtle flicker on the house windows, jack-o'-lanterns, and the hanging lantern.
  - Uses the previous banner spacing.
*/
(function () {
  "use strict";

  const CONFIG = {
    imageWidth: 1448,
    imageHeight: 1086,
    reserveTopBarSpace: true,
    extraTopOffset: 0,
    maxBannerHeight: null,
    minBannerHeight: null,
    animationOpacity: 1,
    contentPullUp: 0,
    backgroundImageDataUri: "data:image/png;base64,"
  };

  const PUMPKIN_GLOWS = [
    { x: 245, y: 985, r: 108, strength: 1.00, phase: 0.1 },
    { x: 395, y: 1010, r: 46, strength: 0.72, phase: 1.3 },
    { x: 1180, y: 985, r: 108, strength: 0.98, phase: 2.1 }
  ];

  const WINDOW_GLOWS = [
    { x: 667, y: 689, r: 50, strength: 0.36, phase: 0.4 },
    { x: 667, y: 590, r: 44, strength: 0.30, phase: 1.7 },
    { x: 573, y: 742, r: 36, strength: 0.26, phase: 1.1 },
    { x: 784, y: 808, r: 42, strength: 0.20, phase: 2.0 },
    { x: 891, y: 735, r: 70, strength: 0.28, phase: 0.9 },
    { x: 969, y: 813, r: 94, strength: 0.25, phase: 2.6 },
    { x: 798, y: 812, r: 58, strength: 0.22, phase: 3.2 },
    { x: 549, y: 820, r: 54, strength: 0.20, phase: 2.4 }
  ];

  const LANTERN_GLOWS = [
    { x: 1371, y: 507, r: 60, strength: 0.58, phase: 0.8 }
  ];

  function ready(fn) {
    if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", fn, { once: true });
    else fn();
  }

  function px(value) {
    return typeof value === "number" ? value + "px" : value;
  }

  ready(function initHauntedHero() {
    if (document.getElementById("ct-haunted-hero")) return;

    const style = document.createElement("style");
    style.id = "ct-haunted-hero-style";
    style.textContent = `
      html, body { min-height: 100%; background: #071026 !important; }
      #ct-haunted-hero {
        position: relative;
        width: 100%;
        overflow: hidden;
        pointer-events: none;
        background-image: url("${CONFIG.backgroundImageDataUri}");
        background-repeat: no-repeat;
        background-position: center center;
        background-size: 100% 100%;
        background-color: #071026;
        box-shadow: inset 0 -60px 60px rgba(7,16,38,0.35);
        margin: 0 !important;
        transform: translateZ(0);
      }
      #ct-haunted-hero canvas {
        position: absolute;
        inset: 0;
        width: 100%;
        height: 100%;
        opacity: ${CONFIG.animationOpacity};
        z-index: 1;
      }
    `;
    document.head.appendChild(style);

    const hero = document.createElement("div");
    hero.id = "ct-haunted-hero";
    const canvas = document.createElement("canvas");
    hero.appendChild(canvas);

    const target = document.querySelector("#wrap") || document.querySelector("#main") || document.querySelector(".container");
    const insertedInsideTarget = !!target;
    if (target) target.prepend(hero);
    else document.body.prepend(hero);

    const ctx = canvas.getContext("2d", { alpha: true });
    let w = 0, h = 0, dpr = 1, map = null;
    let lastFrame = performance.now();
    let flickerSeed = 0;

    function detectTopBarOffset() {
      if (!CONFIG.reserveTopBarSpace) return 0;
      const selectors = ["#nav-collapsible", ".navbar", "nav.navbar", "header", "#header", ".header"];
      let offset = 0;
      for (const sel of selectors) {
        const nodes = document.querySelectorAll(sel);
        for (const el of nodes) {
          const cs = getComputedStyle(el);
          if ((cs.position === "fixed" || cs.position === "sticky") && cs.display !== "none" && cs.visibility !== "hidden") {
            const rect = el.getBoundingClientRect();
            if (rect.bottom > 0 && rect.top < 120 && rect.width > window.innerWidth * 0.35) {
              offset = Math.max(offset, rect.bottom);
            }
          }
        }
      }
      return Math.ceil(offset + (CONFIG.extraTopOffset || 0));
    }

    function tightenGap() {
      if (CONFIG.contentPullUp && hero.nextElementSibling) {
        const next = hero.nextElementSibling;
        next.style.marginTop = '-' + CONFIG.contentPullUp + 'px';
        next.style.position = next.style.position || 'relative';
        next.style.zIndex = next.style.zIndex || '1';
      }
    }

    function updateHeroLayout() {
      const width = Math.max(1, hero.clientWidth || window.innerWidth || 1);
      let height = Math.round(width * CONFIG.imageHeight / CONFIG.imageWidth);
      if (CONFIG.minBannerHeight != null) height = Math.max(height, parseInt(CONFIG.minBannerHeight, 10));
      if (CONFIG.maxBannerHeight != null) height = Math.min(height, parseInt(CONFIG.maxBannerHeight, 10));
      hero.style.height = px(height);
      hero.style.marginTop = insertedInsideTarget ? '0px' : px(detectTopBarOffset());
      hero.style.marginBottom = '0px';
      if (insertedInsideTarget && target) {
        target.style.paddingTop = '0px';
        target.style.marginTop = '0px';
      }
      tightenGap();
    }

    function computeMap() {
      const iw = CONFIG.imageWidth, ih = CONFIG.imageHeight;
      const sx = w / iw, sy = h / ih;
      const scale = Math.min(sx, sy);
      const drawW = iw * scale;
      const drawH = ih * scale;
      return { scale, ox: (w - drawW) / 2, oy: (h - drawH) / 2 };
    }

    function imgToScreen(x, y) {
      return { x: map.ox + x * map.scale, y: map.oy + y * map.scale };
    }

    function resize() {
      updateHeroLayout();
      dpr = Math.max(1, Math.min(2, window.devicePixelRatio || 1));
      w = Math.max(1, hero.clientWidth);
      h = Math.max(1, hero.clientHeight);
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
      canvas.style.width = w + "px";
      canvas.style.height = h + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      map = computeMap();
    }

    function glow(cx, cy, radius, alpha, coreAlpha) {
      const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, radius);
      g.addColorStop(0.00, `rgba(255, 231, 112, ${coreAlpha})`);
      g.addColorStop(0.22, `rgba(255, 164, 36, ${alpha})`);
      g.addColorStop(0.55, `rgba(255, 99, 16, ${alpha * 0.26})`);
      g.addColorStop(1.00, "rgba(255, 80, 0, 0)");
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(cx, cy, radius, 0, Math.PI * 2);
      ctx.fill();
    }

    function drawFlicker(t) {
      ctx.save();
      ctx.globalCompositeOperation = "screen";
      for (const p of PUMPKIN_GLOWS) {
        const pos = imgToScreen(p.x, p.y);
        const pulse = 0.78 + 0.20 * Math.sin(t * 0.006 + p.phase) + 0.08 * Math.sin(t * 0.021 + p.phase * 3 + flickerSeed);
        glow(pos.x, pos.y, p.r * map.scale, Math.max(0, p.strength * pulse * 0.34), Math.max(0, p.strength * pulse * 0.16));
      }
      for (const win of WINDOW_GLOWS) {
        const pos = imgToScreen(win.x, win.y);
        const pulse = 0.70 + 0.18 * Math.sin(t * 0.0045 + win.phase) + 0.10 * Math.sin(t * 0.013 + win.phase * 2.4);
        glow(pos.x, pos.y, win.r * map.scale, Math.max(0, win.strength * pulse * 0.22), Math.max(0, win.strength * pulse * 0.10));
      }
      for (const lan of LANTERN_GLOWS) {
        const pos = imgToScreen(lan.x, lan.y);
        const pulse = 0.82 + 0.14 * Math.sin(t * 0.0055 + lan.phase) + 0.06 * Math.sin(t * 0.017 + lan.phase * 2.8 + flickerSeed * 1.5);
        glow(pos.x, pos.y, lan.r * map.scale, Math.max(0, lan.strength * pulse * 0.28), Math.max(0, lan.strength * pulse * 0.14));
      }
      ctx.restore();
    }

    function frame(now) {
      const dt = now - lastFrame;
      lastFrame = now;
      if (dt > 0) flickerSeed += dt * 0.0006;
      ctx.clearRect(0, 0, w, h);
      if (map) drawFlicker(now);
      requestAnimationFrame(frame);
    }

    window.addEventListener("resize", resize, { passive: true });
    window.addEventListener("load", resize, { passive: true });
    if (window.ResizeObserver) new ResizeObserver(resize).observe(hero);
    resize();
    requestAnimationFrame(frame);
  });
})();
